1	import { notFound } from "next/navigation";
2	import Link from "next/link";
3	import { db } from "@/lib/db";
4	import { requireUser } from "@/lib/auth";
5	import {
6	  getDnsHosts,
7	  registrarConfigured,
8	  registrarSafeMessage,
9	  transferStatusLabel,
10	  type DnsHost,
11	} from "@/lib/registrar";
12	import { transferChargeCents } from "@/lib/domain-transfer";
13	import { TransferInStatusCard } from "@/components/customer/DomainTransferIn";
14	import { getRegistrarLock, listRedirects } from "@/lib/actions-domains-dns";
15	import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
16	import { fmtMoney } from "@/components/ui/primitives";
17	import { AutoRefresh } from "@/components/AutoRefresh";
18	import { PageShell } from "@/components/nx/PageShell";
19	import { DomainsAurora } from "@/components/nx/DomainsAurora";
20	import type { QuickServer } from "@/components/customer/DnsQuickSetup";
21	import { DomainDetailShell } from "@/components/customer/DomainDetailShell";
22	import { type ChecklistItem } from "@/components/customer/DomainChecklist";
23	
24	export const dynamic = "force-dynamic";
25	
26	function daysUntil(d: Date): number {
27	  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
28	}
29	
30	function expiryNote(d: Date | null): { text: string; tone: "green" | "amber" | "red" | "slate" } {
31	  if (!d) return { text: "—", tone: "slate" };
32	  const days = daysUntil(d);
33	  if (days < 0) return { text: `expired ${-days} days ago`, tone: "red" };
34	  if (days === 0) return { text: "expires today", tone: "red" };
35	  if (days <= 30) return { text: `in ${days} days`, tone: "amber" };
36	  return { text: `in ${days} days`, tone: "green" };
37	}
38	
39	const STATUS_META: Record<string, { label: string; tone: "amber" | "rose" | "cyan" | "mint" | "slate" }> = {
40	  ACTIVE: { label: "Active", tone: "mint" },
41	  PENDING: { label: "Pending", tone: "amber" },
42	  TRANSFER_PENDING: { label: "Transfer pending", tone: "amber" },
43	  EXPIRED: { label: "Expired", tone: "rose" },
44	  FAILED: { label: "Failed", tone: "rose" },
45	  TRANSFER_FAILED: { label: "Transfer failed", tone: "rose" },
46	};
47	
48	export default async function DomainPage({
49	  params,
50	  searchParams,
51	}: {
52	  params: Promise<{ id: string }>;
53	  searchParams: Promise<{ new?: string }>;
54	}) {
55	  const { id } = await params;
56	  const { new: justRegistered } = await searchParams;
57	  const user = await requireUser();
58	  const domain = await db.domain.findUnique({ where: { id } });
59	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) notFound();
60	
61	  const publicIp = process.env.PUBLIC_IP ?? "";
62	  const active = domain.status === "ACTIVE";
63	  const showGoLive = justRegistered === "1" && active;
64	
65	  // The user's own servers — targets for the "point at my server" preset.
66	  const servers = await db.server.findMany({
67	    where: { userId: domain.userId },
68	    include: { dedicatedIp: true, node: { select: { publicIp: true } } },
69	    orderBy: { createdAt: "desc" },
70	  });
71	  const quickServers: QuickServer[] = servers.map((s) => ({
72	    id: s.id,
73	    label: s.label || s.name || s.hostname,
74	    ip: s.dedicatedIp?.address || s.node?.publicIp || "",
75	  }));
76	
77	  let dnsHosts: DnsHost[] | null = null;
78	  let dnsError: string | null = null;
79	  if (active && registrarConfigured()) {
80	    try {
81	      dnsHosts = await getDnsHosts(domain.name);
82	    } catch (e) {
83	      dnsError = registrarSafeMessage(e);
84	    }
85	  }
86	
87	  const [lockView, redirectsView] = await Promise.all([
88	    getRegistrarLock(domain.id),
89	    listRedirects(domain.id),
90	  ]);
91	
92	  let hostingFromCents: number | null = null;
93	  let vpsFromCents: number | null = null;
94	  if (showGoLive) {
95	    const [hostingPlans, vpsPlans] = await Promise.all([
96	      db.hostingPlan.findMany({ where: { active: true }, select: { priceCents: true } }),
97	      db.plan.findMany({ where: { active: true }, select: { priceCents: true } }),
98	    ]);
99	    hostingFromCents = hostingPlans.length ? Math.min(...hostingPlans.map((p) => p.priceCents)) : null;
100	    vpsFromCents = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;
101	  }
102	
103	  // ----- Setup checklist -----
104	  const knownIps = new Set<string>([publicIp, ...quickServers.map((s) => s.ip)].filter(Boolean));
105	  const apexRecords = (dnsHosts ?? []).filter((h) => h.name === "@" || h.name === "www");
106	  const pointedAtServer = apexRecords.some(
107	    (h) => (h.type === "A" && knownIps.has(h.address)) || h.type === "CNAME" || h.type === "ALIAS"
108	  );
109	  const emailConfigured = (dnsHosts ?? []).some((h) => h.type === "MX");
110	  const checklist: ChecklistItem[] = [
111	    {
112	      label: domain.isTransferIn ? "Domain transferred in" : "Domain registered",
113	      done: active,
114	      hint: domain.isTransferIn
115	        ? "The transfer is still running — approve the confirmation email from your old registrar."
116	        : "Registration is still processing.",
117	    },
118	    { label: "Pointed at a server", done: pointedAtServer, hint: "Use Quick setup → “Point this domain at my server”." },
119	    { label: "Email configured", done: emailConfigured, hint: "Add MX records via Quick setup → Google Workspace, or your mail host." },
120	    { label: "WHOIS privacy on", done: domain.whoisPrivacy, hint: "Turn on WHOIS privacy under Security." },
121	    { label: "Auto-renew on", done: domain.autoRenew, hint: "Enable auto-renew so it never lapses." },
122	  ];
123	
124	  const meta = STATUS_META[domain.status] ?? { label: domain.status, tone: "slate" as const };
125	  const term = domainTerm(domain.termYears);
126	  const renewPerYearCents = (domain as any).renewPriceCents ?? domain.priceCents;
127	  const renewTotal = domainTermPriceCents(renewPerYearCents, term.years);
128	  const exp = expiryNote(domain.expiresAt);
129	
130	  return (
131	    <>
132	      <DomainsAurora />
133	
134	      {/* No full-screen Provisioning takeover here, deliberately — domain
135	          registration is synchronous, so there is no real multi-step progress
136	          to show, and every one of PENDING/FAILED/just-registered already has
137	          its own honest, inline banner below (the amber "being processed"
138	          note, the red failure card, the green go-live card). A takeover
139	          screen on top of those said the same thing twice and buried the
140	          hero's own aurora under an opaque panel. */}
141	      {domain.status === "PENDING" && <AutoRefresh />}
142	
143	      <PageShell eyebrow="NETWORK" title={domain.name} sub="Domain management" wisp={false}>
144	        <div className="-mt-2 mb-1 flex flex-wrap items-center gap-3">
145	          <span className={"nx-tag nx-tag-" + meta.tone + (meta.tone === "amber" ? " nx-tag-pulse" : "")}>
146	            <span className="nx-tag-dot" aria-hidden />
147	            {meta.label}
148	          </span>
149	          <span className="text-[12.5px] text-tx-dim">
150	            Registered {domain.registeredAt ? domain.registeredAt.toISOString().slice(0, 10) : "—"}
151	            {domain.expiresAt && <> · Renews {domain.expiresAt.toISOString().slice(0, 10)} ({exp.text})</>}
152	          </span>
153	          <Link href="/dashboard/domains" className="btn-ghost ml-auto text-xs">← All domains</Link>
154	        </div>
155	
156	        {showGoLive && (
157	          <div className="card mb-5 border-emerald-500/30 bg-emerald-500/[0.06]">
158	            <div className="flex items-start gap-3">
159	              <span className="mt-0.5 flex h-9 w-9 flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300">
160	                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
161	                  <path d="M20 6 9 17l-5-5" />
162	                </svg>
163	              </span>
164	              <div>
165	                <h2 className="font-semibold text-white">{domain.name} is registered</h2>
166	                <p className="mt-1 text-sm text-slate-300">
167	                  Now let&apos;s get something live on it. Add hosting or a VPS and point this domain at it in a
168	                  couple of clicks.
169	                </p>
170	              </div>
171	            </div>
172	            <div className="mt-4 grid gap-4 sm:grid-cols-2">
173	              <div className="rounded-xl border border-rim-hi bg-well p-4">
174	                <p className="text-sm font-semibold text-white">Shared Web Hosting</p>
175	                <p className="mt-1 text-xs leading-relaxed text-tx-dim">
176	                  PHP, MySQL, free SSL, and a free bundled mailbox on this domain.
177	                  {hostingFromCents !== null && <> Plans from {fmtMoney(hostingFromCents)}/mo — first month free.</>}
178	                </p>
179	                <Link href="/web-hosting" className="btn-secondary mt-3 px-3 py-1.5 text-xs">See hosting plans</Link>
180	              </div>
181	              <div className="rounded-xl border border-rim-hi bg-well p-4">
182	                <p className="text-sm font-semibold text-white">NVMe VPS</p>
183	                <p className="mt-1 text-xs leading-relaxed text-tx-dim">
184	                  Full root access for apps, game servers, or anything shared hosting can&apos;t run.
185	                  {vpsFromCents !== null && <> Plans from {fmtMoney(vpsFromCents)}/mo.</>}
186	                </p>
187	                <Link href="/vps" className="btn-secondary mt-3 px-3 py-1.5 text-xs">See VPS plans</Link>
188	              </div>
189	            </div>
190	          </div>
191	        )}
192	
193	        {domain.status === "FAILED" && (
194	          <div className="card mb-5 border-red-500/30 text-sm text-red-300">
195	            Registration failed{domain.error ? `: ${domain.error}` : "."} You were refunded — try again or
196	            contact support.
197	          </div>
198	        )}
199	
200	        {domain.status === "PENDING" && !domain.isTransferIn && (
201	          <div className="card mb-5 border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-200">
202	            Registration is being processed. This page refreshes automatically — it usually completes within
203	            a minute.
204	          </div>
205	        )}
206	
207	        {domain.isTransferIn && (domain.status === "TRANSFER_PENDING" || domain.status === "TRANSFER_FAILED") && (
208	          <div className="mb-5">
209	            <TransferInStatusCard
210	              domainId={domain.id}
211	              domainName={domain.name}
212	              status={domain.status}
213	              transferStatus={domain.transferStatus}
214	              transferStatusLabel={domain.transferStatus ? transferStatusLabel(domain.transferStatus) : null}
215	              transferEmail={domain.transferEmail}
216	              transferStartedAt={domain.transferStartedAt ? domain.transferStartedAt.toISOString() : null}
217	              priceCents={transferChargeCents(domain.priceCents)}
218	              error={domain.error}
219	            />
220	          </div>
221	        )}
222	
223	        <DomainDetailShell
224	          domain={{
225	            id: domain.id,
226	            name: domain.name,
227	            status: domain.status,
228	            registeredAt: domain.registeredAt ? domain.registeredAt.toISOString() : null,
229	            expiresAt: domain.expiresAt ? domain.expiresAt.toISOString() : null,
230	            autoRenew: domain.autoRenew,
231	            whoisPrivacy: domain.whoisPrivacy,
232	            nameservers: domain.nameservers,
233	          }}
234	          active={active}
235	          statusLabel={meta.label}
236	          statusTone={meta.tone}
237	          exp={exp}
238	          term={term}
239	          renewPerYearCents={renewPerYearCents}
240	          renewTotal={renewTotal}
241	          checklist={checklist}
242	          registrarConfigured={registrarConfigured()}
243	          quickServers={quickServers}
244	          publicIp={publicIp}
245	          dnsHosts={dnsHosts}
246	          dnsError={dnsError}
247	          redirectsView={redirectsView}
248	          lockView={lockView}
249	          hasEpp={!!domain.transferEpp}
250	        />
251	      </PageShell>
252	    </>
253	  );
254	}
