1	"use client";
2	
3	import { useActionState, useState, useTransition } from "react";
4	import {
5	  renewDomainAction,
6	  toggleDomainAutoRenew,
7	  addDnsRecord,
8	  deleteDnsRecord,
9	  pointDomainAtServer,
10	} from "@/lib/actions-domains";
11	import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
12	import { fmtMoney } from "@/components/ui/primitives";
13	
14	export function DomainAutoRenewToggle({
15	  domainId,
16	  autoRenew,
17	}: {
18	  domainId: string;
19	  autoRenew: boolean;
20	}) {
21	  const [pending, start] = useTransition();
22	  const [error, setError] = useState<string | null>(null);
23	  return (
24	    <span className="inline-flex items-center gap-2">
25	      {error && <span className="text-xs text-red-400">{error}</span>}
26	      <button
27	        type="button"
28	        role="switch"
29	        aria-checked={autoRenew}
30	        aria-label="Auto-renew this domain"
31	        disabled={pending}
32	        onClick={() =>
33	          // Previously the returned/thrown result was DISCARDED, so a failed
34	          // toggle (e.g. Forbidden) was a silent no-op — the switch snapped back
35	          // on the next render with no explanation. Capture and surface it inline.
36	          start(async () => {
37	            setError(null);
38	            try {
39	              const res = (await toggleDomainAutoRenew(domainId)) as { error?: string } | void;
40	              if (res?.error) setError(res.error);
41	            } catch {
42	              setError("Couldn’t update auto-renew — try again.");
43	            }
44	          })
45	        }
46	        title={autoRenew ? "Auto-renew is on — click to turn off" : "Auto-renew is off — click to turn on"}
47	        className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400 disabled:opacity-50 ${
48	          autoRenew ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
49	        }`}
50	      >
51	        <span
52	          className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
53	            autoRenew ? "left-[18px]" : "left-0.5"
54	          }`}
55	        />
56	      </button>
57	    </span>
58	  );
59	}
60	
61	export function RenewDomainButton({
62	  domainId,
63	  priceCents,
64	  termYears,
65	}: {
66	  domainId: string;
67	  priceCents: number;
68	  termYears: number;
69	}) {
70	  const [pending, start] = useTransition();
71	  const [error, setError] = useState<string | null>(null);
72	  const term = domainTerm(termYears);
73	  const total = domainTermPriceCents(priceCents, term.years);
74	  return (
75	    <div>
76	      <button
77	        className="btn-primary w-full"
78	        disabled={pending}
79	        onClick={() => {
80	          if (!window.confirm(`Renew this domain for ${term.label} (${fmtMoney(total)})?`)) return;
81	          start(async () => {
82	            setError(null);
83	            const res = await renewDomainAction(domainId);
84	            if (res?.error) setError(res.error);
85	          });
86	        }}
87	      >
88	        {pending ? "Renewing…" : `Renew now (+${term.label}, ${fmtMoney(total)})`}
89	      </button>
90	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
91	    </div>
92	  );
93	}
94	
95	export function PointAtServerButton({ domainId, ip }: { domainId: string; ip: string }) {
96	  const [pending, start] = useTransition();
97	  const [error, setError] = useState<string | null>(null);
98	  const [done, setDone] = useState(false);
99	  return (
100	    <div>
101	      <button
102	        className="btn-secondary"
103	        disabled={pending}
104	        onClick={() => {
105	          if (
106	            !window.confirm(
107	              `Point @ and www at ${ip}? Existing A records for @ and www will be replaced.`
108	            )
109	          )
110	            return;
111	          start(async () => {
112	            setError(null);
113	            setDone(false);
114	            const res = await pointDomainAtServer(domainId);
115	            if (res?.error) setError(res.error);
116	            else setDone(true);
117	          });
118	        }}
119	      >
120	        {pending ? "Updating DNS…" : "Point at my server"}
121	      </button>
122	      {done && (
123	        <p className="mt-2 text-sm text-emerald-400">
124	          DNS updated — propagation can take up to an hour.
125	        </p>
126	      )}
127	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
128	    </div>
129	  );
130	}
131	
132	const DNS_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV"] as const;
133	const TTL_PRESETS = [
134	  [300, "5 min"],
135	  [1800, "30 min"],
136	  [3600, "1 hour"],
137	  [14400, "4 hours"],
138	  [86400, "1 day"],
139	] as const;
140	
141	const placeholders: Record<string, string> = {
142	  A: "203.0.113.10",
143	  AAAA: "2001:db8::1",
144	  CNAME: "target.example.com",
145	  TXT: "v=spf1 include:_spf.example.com ~all",
146	  MX: "mail.example.com",
147	  NS: "ns1.example.com",
148	  SRV: "10 5 5060 sip.example.com",
149	};
150	
151	const hints: Record<string, string> = {
152	  A: "Points a name at an IPv4 address.",
153	  AAAA: "Points a name at an IPv6 address.",
154	  CNAME: "Aliases this name to another hostname.",
155	  TXT: "Free-form text — SPF, DKIM, domain verification.",
156	  MX: "Mail server for the domain. Lower priority wins.",
157	  NS: "Delegates a subdomain to other nameservers.",
158	  SRV: "Service record: weight port target.",
159	};
160	
161	export function DnsAddForm({ domainId }: { domainId: string }) {
162	  const [state, action, pending] = useActionState(addDnsRecord, {} as { error?: string });
163	  const [type, setType] = useState<string>("A");
164	  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
165	  // `<form action={fn}>` submit — including a REJECTED one. `addDnsRecord`
166	  // returns `{error}` for a malformed value or a name collision, so an
167	  // uncontrolled field blanked the entire Value the customer just pasted — a
168	  // long DKIM/SPF TXT string or a CNAME target — at the exact moment the red
169	  // error told them to fix it, leaving nothing to fix. Same reset class as
170	  // TicketForms.tsx and the port-forward form.
171	  const [name, setName] = useState("");
172	  const [address, setAddress] = useState("");
173	  const needsPriority = type === "MX" || type === "SRV";
174	
175	  return (
176	    <form action={action} className="space-y-4">
177	      <input type="hidden" name="domainId" value={domainId} />
178	      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
179	        <div>
180	          <label className="label">Type</label>
181	          <select className="input" name="type" value={type} onChange={(e) => setType(e.target.value)}>
182	            {DNS_TYPES.map((t) => (
183	              <option key={t} value={t}>
184	                {t}
185	              </option>
186	            ))}
187	          </select>
188	        </div>
189	        <div>
190	          <label className="label">Name</label>
191	          <input
192	            className="input"
193	            name="name"
194	            placeholder="@ or www"
195	            autoComplete="off"
196	            spellCheck={false}
197	            value={name}
198	            onChange={(e) => setName(e.target.value)}
199	          />
200	        </div>
201	        <div className={needsPriority ? "" : "lg:col-span-2"}>
202	          <label className="label">Value</label>
203	          <input
204	            className="input font-mono text-xs"
205	            name="address"
206	            placeholder={placeholders[type] ?? "value"}
207	            required
208	            autoComplete="off"
209	            spellCheck={false}
210	            value={address}
211	            onChange={(e) => setAddress(e.target.value)}
212	          />
213	        </div>
214	        {needsPriority && (
215	          <div>
216	            <label className="label">Priority</label>
217	            <input className="input" name="mxPref" type="number" min={0} max={65535} defaultValue={10} />
218	          </div>
219	        )}
220	        <div>
221	          <label className="label">TTL</label>
222	          <select className="input" name="ttl" defaultValue={1800}>
223	            {TTL_PRESETS.map(([v, label]) => (
224	              <option key={v} value={v}>
225	                {label}
226	              </option>
227	            ))}
228	          </select>
229	        </div>
230	      </div>
231	
232	      <div className="flex flex-wrap items-center justify-between gap-3">
233	        <p className="text-xs text-slate-500">{hints[type]}</p>
234	        <button className="btn-primary" disabled={pending}>
235	          {pending ? "Adding…" : "Add record"}
236	        </button>
237	      </div>
238	      {state?.error && (
239	        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
240	          {state.error}
241	        </div>
242	      )}
243	    </form>
244	  );
245	}
246	
247	export function DnsDeleteButton({
248	  domainId,
249	  record,
250	}: {
251	  domainId: string;
252	  record: { name: string; type: string; address: string };
253	}) {
254	  const [pending, start] = useTransition();
255	  const [error, setError] = useState<string | null>(null);
256	  return (
257	    <span className="inline-flex items-center gap-2">
258	      {error && <span className="text-xs text-red-400">{error}</span>}
259	      <button
260	        className="btn-danger px-2.5 py-1 text-xs"
261	        disabled={pending}
262	        title="Delete record"
263	        onClick={() => {
264	          if (!window.confirm(`Delete ${record.type} record "${record.name}"?`)) return;
265	          start(async () => {
266	            setError(null);
267	            const res = await deleteDnsRecord(domainId, record);
268	            if (res?.error) setError(res.error);
269	          });
270	        }}
271	      >
272	        {pending ? "…" : "Delete"}
273	      </button>
274	    </span>
275	  );
276	}
