1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import type { User } from "@prisma/client";
7	import { db } from "./db";
8	import { requireUser, assertNotImpersonating } from "./auth";
9	import {
10	  registrarConfigured,
11	  registrarSafeMessage,
12	  checkDomains,
13	  registerDomain,
14	  renewDomain,
15	  domainInfo,
16	  listRecords,
17	  addRecord,
18	  deleteRecord,
19	  type RegistrantContact,
20	} from "./registrar";
