552	/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
553	export async function listTransfers(): Promise<TransferInfo[]> {
554	  if (SANDBOX) return [];
555	  const json = await nc("GET", "/v4/transfers");
556	  return (json.transfers ?? []).map((t: any) => ({
557	    domain: t.domainName,
558	    status: String(t.status ?? "pending"),
559	    email: t.email ? String(t.email) : null,
560	  }));
