160	/**
161	 * Request a one-click certificate for `domain` on one of the caller's
162	 * servers — Let's Encrypt (free, default) or a paid CA (RapidSSL/Sectigo,
163	 * `issuer`). Validates the domain, checks server ownership, applies the
164	 * shared rate-limit guard, creates a PENDING SslCertificate row and enqueues
165	 * an SSL_ISSUE job. Charging the customer for a paid issuer is NOT done
166	 * here — no price has been set yet (see PAID_ISSUERS above) — the job will
167	 * fail loudly at issuance time until that's wired up and ENABLE_PAID_SSL is
168	 * set (worker/ssl.ts).
169	 */
170	export async function requestCertificate(
171	  serverId: string,
172	  domain: string,
173	  issuer: Issuer = "letsencrypt"
174	): Promise<{ error?: string; id?: string }> {
175	  let ctx;
176	  try {
177	    ctx = await ownedServer(serverId);
178	  } catch (e: any) {
179	    return { error: e.message };
180	  }
181	  const { user, server } = ctx;
182	
183	  const clean = String(domain ?? "").toLowerCase().trim().replace(/\.$/, "");
184	  if (!FQDN_RE.test(clean)) {
185	    return { error: "Enter a valid domain name (e.g. app.example.com) — no protocol, port or wildcard." };
186	  }
187	
188	  // One active/in-flight cert per (user, domain): don't let a customer stack
189	  // duplicate issue jobs for the same hostname.
190	  const existing = await db.sslCertificate.findFirst({
191	    where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
192	  });
193	  if (existing) {
194	    return {
195	      error:
196	        existing.status === "ACTIVE"
197	          ? `You already have an active certificate for ${clean}.`
198	          : `A certificate for ${clean} is already being issued.`,
199	    };
200	  }
201	
202	  // The duplicate check above is defeated by delete-and-retry, so the weekly
203	  // rate-limit guard is the thing that actually stops a retry loop from burning
204	  // Let's Encrypt's limit. Shared with paid issuers too for now — GoGetSSL has
205	  // its own, different reissue policy, but reusing this counter only ever
206	  // errs toward being MORE conservative (blocking a paid attempt after LE
207	  // attempts on the same domain are exhausted), never less safe. Split this
208	  // once paid-CA billing/UI is actually built.
209	  const rate = await issueAttemptsFor(clean);
210	  if (rateLimited(rate)) return { error: rateLimitMessage(clean, rate) };
211	
212	  // One in-flight job per server — the platform's own invariant, which
213	  // `renewCertificate` below already honours and this path did not. It matters
214	  // more here than there: certbot needs the box in a steady state, so an
215	  // SSL_ISSUE queued behind a REINSTALL or a RESIZE runs against a machine that
216	  // is being wiped or resized underneath it. That attempt fails, and it still
217	  // consumes one of the customer's five weekly Let's Encrypt slots.
218	  const busy = await db.job.count({
219	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
220	  });
221	  if (busy > 0) {
222	    return {
223	      error:
224	        "Another operation is already queued for this server. The platform runs one job at a time, and a " +
225	        "certificate issued mid-rebuild would fail and burn one of your weekly Let's Encrypt attempts — " +
226	        "try again once the current job finishes.",
227	    };
228	  }
229	
230	  const cert = await db.sslCertificate.create({
231	    data: {
232	      userId: user.id,
233	      serverId: server.id,
234	      domain: clean,
235	      status: "PENDING",
236	      issuer,
237	    },
238	  });
239	  await db.job.create({
240	    // `domain` is carried in the payload because the rate-limit counter above
241	    // keys on the hostname and must survive the certificate row being deleted.
242	    data: { type: "SSL_ISSUE", serverId: server.id, payload: { certId: cert.id, domain: clean } },
243	  });
244	  await db.auditLog.create({
245	    data: { userId: user.id, action: "ssl.request", detail: `${clean} on ${server.hostname}` },
246	  });
247	  revalidatePath("/dashboard/ssl");
248	  return { id: cert.id };
249	}
