251	/**
252	 * Reissue a certificate now (owner only), for an ACTIVE/EXPIRED/FAILED row.
253	 *
254	 * Shares the weekly counter with requestCertificate and the worker's renewal
255	 * sweep, so a customer hammering this button cannot exhaust Let's Encrypt's
256	 * duplicate-certificate limit.
257	 */
258	export async function renewCertificate(id: string): Promise<{ error?: string }> {
259	  let ctx;
260	  try {
261	    ctx = await ownedCertificate(id);
262	  } catch (e: any) {
263	    return { error: e.message };
264	  }
265	  const { user, cert } = ctx;
266	
267	  if (!["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status)) {
268	    return { error: "This certificate is already being worked on — wait for the current attempt to finish." };
269	  }
270	  if (!cert.serverId) {
271	    return { error: "This certificate is not attached to a server, so it cannot be issued." };
272	  }
273	  if (await liveIssueJob(cert.id)) {
274	    return { error: "An issue job for this certificate is already queued." };
275	  }
276	
277	  const rate = await issueAttemptsFor(cert.domain);
278	  if (rateLimited(rate)) return { error: rateLimitMessage(cert.domain, rate) };
279	
280	  // One in-flight job per server, matching the worker's own invariant.
281	  const busy = await db.job.count({
282	    where: { serverId: cert.serverId, status: { in: ["QUEUED", "RUNNING"] } },
283	  });
284	  if (busy > 0) {
285	    return {
286	      error:
287	        "Another operation is already queued for this server. The platform runs one job at a time — try again once it finishes.",
288	    };
289	  }
290	
291	  await db.job.create({
292	    data: {
293	      type: "SSL_ISSUE",
294	      serverId: cert.serverId,
295	      // `renewal: true` keeps a still-valid certificate ACTIVE if the reissue
296	      // fails, instead of flipping a working site's row to FAILED.
297	      payload: { certId: cert.id, domain: cert.domain, renewal: true },
298	    },
299	  });
300	  await db.auditLog.create({
301	    data: { userId: user.id, action: "ssl.renew", detail: `${cert.domain}` },
302	  });
303	  revalidatePath("/dashboard/ssl");
304	  return {};
305	}
