330	        error:
331	          "certbot is running for this domain right now — deleting mid-issue would leave a certificate on the " +
332	          "server with no record of it. Try again in a minute.",
333	      };
334	    }
335	    if (live) {
336	      // Queued but not started: cancel it, otherwise the worker would pick up a
337	      // job whose certificate row no longer exists and log a spurious failure.
338	      await db.job.updateMany({
339	        where: { id: live.id, status: "QUEUED" },
340	        data: {
341	          status: "FAILED",
342	          error: "Cancelled — the customer deleted the certificate request before it started.",
343	        },
344	      });
345	    }
346	  }
347	
348	  await db.sslCertificate.delete({ where: { id } });
349	  await db.auditLog.create({
350	    data: { userId: user.id, action: "ssl.delete", detail: `${cert.domain}` },
351	  });
352	  revalidatePath("/dashboard/ssl");
353	  return {};
354	}
