571	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
572	  // token table. A rapid resubmit or a network retry with the same key can't create
573	  // a second account or take a second debit.
574	  const sessionKey = `hostorder:${key}`;
575	  try {
576	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
577	  } catch (e) {
