579	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
580	      // A completed prior attempt: replay its result (no second charge).
581	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
582	      // A failed prior attempt: clear it so an explicit retry can proceed.
583	      if (prior?.status === "FAILED") {
