587	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
588	      }
589	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
590	      try {
591	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
592	      } catch {
593	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
594	      }
595	    } else {
